import{z as s,x as p,o as E,c as B,q as A,j as r,D as e,d as i,s as n,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"SRAM 单元图形化","description":"","frontmatter":{"title":"SRAM 单元图形化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/sram-cell-patterning.md","filePath":"litho/sram-cell-patterning.md","lastUpdated":1791413859000}'),d={name:"litho/sram-cell-patterning.md"};function m(D,a,h,C,c,R){const l=p("Mermaid");return E(),B("div",null,[a[2]||(a[2]=A('<h1 id="sram-单元图形化" tabindex="-1">SRAM 单元图形化 <a class="header-anchor" href="#sram-单元图形化" aria-label="Permalink to &quot;SRAM 单元图形化&quot;">​</a></h1><div class="epigraph"><p>SRAM 是全芯片最密、最重复、最不肯让步的二维邻域；逻辑库的轨高合同到这里往往要另开一页。</p><footer>—— 对照先进节点 SRAM 多图形、切线与 EUV 对 bitcell 的公开 DTCO 讨论</footer></div><p><a href="/litho/scaling-boosters">上一课</a>把逻辑密度助推器写成新层。缺口是位元：SRAM 单元面积直接进缓存密度，图形比逻辑更二维、更周期，失败则整宏报废。<a href="/litho/hotspot-pv">热点</a> 已警告 SRAM 拐角；本课钉单元图形化选项。金属与 via 如何协同，留给<a href="/litho/metal-via-co-optimization">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>6T SRAM 的栅、扩散、接触、局部互连挤在最小 CPP 与最小金属节距附近，尖端对尖端、弯折、不对称上拉/下拉是常客。逻辑允许单向金属加切线；SRAM 为面积常保留二维或特殊切线。EUV 单次能消掉一些双重着色，但随机缺孔与桥连在小接触上更狠。SAQP 鳍与切线套刻决定 fin 数与有效宽度，电学失配与图形化绑在一起。</p><p>缺口是<strong>SRAM 专用规则与分解</strong>，不是重讲 SRAM 电路。把逻辑 LRC 规格直接套 bitcell，不是过严害死密度，就是过宽放过周期杀手——周期会把单一热点复制成百万副本。</p><p><span class="marginnote">「6T 单元」翻译一下：用六只晶体管存一个比特——两只负责「这只管是 0 还是 1」的强拉，两只当访问开关，两只做反相器锁存。六个图形全部挤在十几纳米的见方里，所以它是全芯片最难的图形化考题。</span></p><h3 id="周期是双刃" tabindex="-1">周期是双刃 <a class="header-anchor" href="#周期是双刃" aria-label="Permalink to &quot;周期是双刃&quot;">​</a></h3><p>重复使 RCWA、量测垫和 PWQ 矩阵都好做：一个 clips 代表整宏。但也使系统缺陷没有「稀释」：一次切线偏置走样，整片缓存失效。匹配模板必须以 SRAM 为独立族。填充 dummy 在阵列边缘必须设计，否则刻蚀负载在阵列/逻辑边界爆。</p><p><span class="marginnote">bitcell 常有自己的 OPC 配方和允许的 MRC 例外。版本号要与逻辑层分开，避免全芯片核被单元特例污染。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选项：EUV 单次 vs 双重、鳍 SAQP + 切线、接触孔 EUV vs LELE、局部互连是否与逻辑同色规则。评估：单元面积、读写余量对 CD 失配、热点 PV、随机打开、阵列边缘 dummy。计量：阵列内 CD-SEM 与电学 bit 测试互补；只看逻辑 gauge 会漏 SRAM。与轨高课衔接：SRAM 轨/鳍数是另一张表。</p><p>电学 bit 失败要能分：读破坏、写失败、还是开路 via——前两者常是 CD 失配与 pitch walking，后者才是打开随机。混在一张失败率里，会把切线套刻和 EUV 剂量拧到同一旋钮。imec 的 SRAM DTCO 公开材料把图形化选项与余量放在同一张表，本课沿用这张表的结构。</p>',13)),(E(),r(o,null,{default:e(()=>[n(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIT%5B%22%E7%94%B5%E5%AD%A6%20bit%20%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20RD%5B%22%E8%AF%BB%E7%A0%B4%E5%9D%8F%20%2F%20%E5%86%99%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20BIT%20--%3E%20OP%5B%22%E5%BC%80%E8%B7%AF%20via%22%5D%0A%20%20RD%20--%3E%20CD%5B%22CD%20%E5%A4%B1%E9%85%8D%20%2F%20pitch%20walking%22%5D%0A%20%20CD%20--%3E%20KN1%5B%22%E6%97%8B%E9%92%AE%3A%20%E5%88%87%E7%BA%BF%E5%A5%97%E5%88%BB%E4%B8%8E%E9%B3%8D%E6%AD%A5%E8%BF%9B%22%5D%0A%20%20OP%20--%3E%20RND%5B%22%E9%9A%8F%E6%9C%BA%E7%BC%BA%E5%AD%94%22%5D%0A%20%20RND%20--%3E%20KN2%5B%22%E6%97%8B%E9%92%AE%3A%20EUV%20%E5%89%82%E9%87%8F%E4%B8%8E%E5%AD%94%E5%B0%BA%E5%AF%B8%22%5D%0A%20%20KN1%20--%3E%20X%5B%22%E6%8B%A7%E9%94%99%E6%97%8B%E9%92%AE%20%3D%20%E7%99%BD%E7%83%A7%E5%AE%9E%E9%AA%8C%22%5D%0A%20%20KN2%20--%3E%20X%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[i("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"单元面积 \\(\\approx\\) \\(x\\)-节距 \\(\\times\\) \\(y\\)-节距。每一边被栅节距、鳍节距、接触尺寸、套刻和 tip 卡住。多图形把 \\(x\\) 或 \\(y\\) 拆到不同掩模，pitch walking 变成失配。EUV 随机把小孔的有效最小面积抬高，可能倒逼单元改拓扑（如接触合并或不同 bitcell 架构）。周期边界的负载效应让阵列中心与边缘 CD 不同，OPC 要分区或用密度核覆盖阵列尺度。",-1)),a[5]||(a[5]=t("p",null,[t("span",{class:"marginnote"},"数字感受一下面积账：若 \\(x\\)、\\(y\\) 节距各 30 nm，单元就是 900 nm²；\\(y\\) 方向从 4 鳍省到 3 鳍，面积直接掉四分之一。SRAM 面积是乘法不是加法——单边节距的小让步在整块缓存上翻倍兑现。")],-1)),a[6]||(a[6]=t("p",null,[t("span",{class:"marginnote"},"「pitch walking」直觉类比：两排地砖本该等距，铺砖时这排往前挪半格，之后每块砖跟着走样。多重图形里第一次曝光偏一点，第二次盖上去就对不齐，CD 随位置 systematically 漂——这就是 SRAM 里最讨厌的失配来源。")],-1)),(E(),r(o,null,{default:e(()=>[n(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20CELL%5B%22bitcell%20%E6%8B%93%E6%89%91%22%5D%20--%3E%20PAT%5B%22%E6%A0%85%20%2F%20%E9%B3%8D%20%2F%20%E6%8E%A5%E8%A7%A6%20%2F%20%E5%B1%80%E9%83%A8%E9%87%91%E5%B1%9E%22%5D%0A%20%20PAT%20--%3E%20DEC%5B%22%E5%88%86%E8%A7%A3%E4%B8%8E%20EUV%20%E9%80%89%E9%A1%B9%22%5D%0A%20%20DEC%20--%3E%20ARR%5B%22%E9%98%B5%E5%88%97%E5%91%A8%E6%9C%9F%20%2B%20%E8%BE%B9%E7%BC%98%20dummy%22%5D%0A%20%20ARR%20--%3E%20Y%5B%22%E8%89%AF%E7%8E%87%20%3D%20%E5%8D%95%E7%BB%86%E8%83%9E%E5%A4%B1%E6%95%88%20%C3%97%20%E5%89%AF%E6%9C%AC%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p>阵列副本把单细胞失效放大成宏级良率。dummy 与分区 OPC 是为了让中心与边缘走同一条路径，而不是装饰填充。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写某厂未公开的 SRAM 面积数字。不把存储阵列的设计规则泄成「通用逻辑规则」。本课不进入量化交易或大模型权重。</p><p>后课默认：SRAM 是独立图形化合同。下一课把互连侧的金属–via 覆盖收成协同，逻辑与 SRAM 都会用到。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SRAM 单元是最密二维周期，规则与 OPC 常与逻辑分家。</li><li>单一热点乘以阵列副本，系统缺陷没有稀释。</li><li>边缘 dummy 与分区 OPC 服务负载，不是装饰。</li><li>电学 bit 失败要分失配、打开与 via，切勿共用一个剂量旋钮。</li><li>出处：imec / 逻辑节点 SRAM DTCO 公开讨论；多重图形与 bitcell 通称。</li></ul>',6))])}const P=s(d,[["render",m]]);export{u as __pageData,P as default};
